type ApiError = { code: string; message: string };
type Profile = { id: string; name: string };

function isApiError(value: unknown): value is ApiError {
  return typeof value === 'object' && value !== null;
}

async function loadProfile(id: string): Promise<Profile> {
  const res = await fetch(`/api/profiles/${id}`);
  const body: unknown = await res.json();
  if (isApiError(body)) {
    throw new Error(body.message);
  }
  return body as Profile;
}

type TipState = { percent: number | null; billCents: number };

function tipLabel({ percent, billCents }: TipState): string {
  if (!percent) {
    return 'Choose a tip';
  }
  const tipCents = Math.round((billCents * percent) / 100);
  return `Tip ${percent}%: ${(tipCents / 100).toFixed(2)}`;
}

function canPay(state: TipState): boolean {
  return state.percent !== null;
}

type RequestState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: string };

function assertNever(x: never): never {
  throw new Error(`Unhandled state: ${JSON.stringify(x)}`);
}

function statusText(state: RequestState<string[]>): string {
  switch (state.status) {
    case 'loading': return 'Loading';
    case 'success': return `${state.data.length} items`;
    case 'error': return state.error;
    default:
      return assertNever(state as never);
  }
}
